#!/usr/bin/env bash\nset -e\n\n# Simple deterministic comment selector\nBASE_IMAGE=\"$1\"\nAPP_TYPE=\"${2:-shell}\"\n\nif [[ -z \"$BASE_IMAGE\" ]]; then\n  echo \"Usage: $0 <base-image> [app]\" >&2\n  exit 1\nfi\n\n# List of whimsical comments\nCOMMENTS=(\n  \"# In the ashes of the old world, we rebuild.\"\n  \"# This layer survived the great firewall.\"\n  \"# Beware the lurking bugs of the wasteland.\"\n  \"# Fuel the container with hope.\"\n  \"# Echoes of the void guide this build.\"\n)\n\n# Deterministic index based on sum of ASCII codes\nsum=0\nfor (( i=0; i<${#BASE_IMAGE}; i++ )); do\n  char=\"${BASE_IMAGE:i:1}\"\n  ascii=$(printf "%d" \"'$char'\")\n  sum=$((sum + ascii))\ndone\nidx=$((sum % ${#COMMENTS[@]}))\n\necho \"${COMMENTS[$idx]}\"\n\ncat <<'EOF' >Dockerfile.tmp\nFROM __BASE__\n__APP_SETUP__\nEOF\n\n# Replace placeholders\ndockerfile=$(sed \"s|__BASE__|$BASE_IMAGE|g\" Dockerfile.tmp)\n\nif [[ \"$APP_TYPE\" == \"python\" ]]; then\n  app_setup=\"RUN apk add --no-cache python3 && echo 'print(\"Hello from the apocalypse!\")' > /app.py && CMD [\"python3\",\"/app.py\"]\"\nelif [[ \"$APP_TYPE\" == \"node\" ]]; then\n  app_setup=\"RUN apk add --no-cache nodejs npm && echo 'console.log(\"Hello from the wasteland!\");' > /app.js && CMD [\"node\",\"/app.js\"]\"\nelse\n  app_setup=\"CMD [\"sh\",\"-c\",\"echo Hello from the void\"]\"\nfi\n\ndockerfile=$(echo \"$dockerfile\" | sed \"s|__APP_SETUP__|$app_setup|g\")\nprintf \"%s\n\" \"$dockerfile\"\n
